import {filmingGuide} from './filming-guide.js';
import {listLookAnswers,mountListLook} from './list-preview.js';

const lrUploads=new Map();
const lrUploadListeners=new Map();
const lrBase='/formats/scroll-reel';
const lrList=x=>Array.isArray(x)?x:[];
const lrURL=x=>typeof x==='string'?x:x?.url||'';
const lrEqual=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const lrParams=ui=>typeof ui.params==='function'?ui.params():ui.params||new URLSearchParams(location.search);
const lrParam=(ui,key)=>lrParams(ui)?.get?.(key)||'';
const lrJobs=s=>{const key=s.workspaceId||'preview';if(!lrUploads.has(key))lrUploads.set(key,new Map());return lrUploads.get(key);};
const lrUploadNotify=s=>{for(const fn of lrUploadListeners.get(s.workspaceId||'preview')||[])fn();};
const lrButton=(ui,label,action,kind='primary',extra='')=>`<button type="button" class="btn ${kind}" data-list-action="${action}" ${extra}>${ui.esc(label)}</button>`;
const lrField=(ui,label,key,value='',area=false,extra='')=>`<label class="field"><span>${ui.esc(label)}</span>${area?`<textarea data-list-field="${key}" rows="3" ${extra}>${ui.esc(value)}</textarea>`:`<input data-list-field="${key}" value="${ui.esc(value)}" ${extra}>`}</label>`;
const lrError=()=>'<p class="lr-error" id="list-error" role="alert"></p>';
const lrTitle=(ui,title,line='',action='')=>`<div class="lr-heading"><div><h1>${ui.esc(title)}</h1>${line?`<p>${ui.esc(line)}</p>`:''}</div>${action}</div>`;
const lrSection=(title,body,action='')=>`<section class="lr-section"><div class="lr-section-head"><h2>${title}</h2>${action}</div>${body}</section>`;
const lrPrompt=(ui,text,action='copy-prompt')=>`<pre class="lr-prompt" id="list-prompt">${ui.esc(text)}</pre>${lrButton(ui,'Copy prompt',action,'primary')}<p class="lr-message">Paste into your Keyframes chat.</p>`;
const lrSafeURL=value=>{try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password?url.href:null;}catch{return null;}};
const lrSource=(ui,url,label='Open source')=>{const safe=lrSafeURL(url);return safe?`<a href="${ui.esc(safe)}" target="_blank" rel="noopener">${ui.esc(label)} ↗</a>`:'';};

export function listSetupDone(f){return Boolean(f?.setup?.savedDone??f?.setup?.done);}
export function listDraft(f,parent){
 const saved=listLookAnswers(f.answers||{},f.listReel?.fonts||[]);
 const d=parent.list??=( {look:saved,lookDirty:false,savedLook:JSON.stringify(saved),count:1,choice:'auto',ideaFilter:'saved',reviews:{},reuse:[],googleDraft:''} );
 d.reviews??={};d.reuse??=[];d.count=Math.min(10,Math.max(1,Number(d.count)||1));
 if(d.pendingLook&&listSetupDone(f)&&lrEqual(saved,d.pendingLook)){d.awaitingSave=false;d.lookDirty=false;d.look=saved;d.savedLook=JSON.stringify(saved);d.saveConfirmed=true;}
 else if(!d.lookDirty&&d.savedLook!==JSON.stringify(saved)){d.look=saved;d.savedLook=JSON.stringify(saved);}
 return d;
}
function lrLiveLink(ui,message='Open the working app to save into your folder.'){
 return `<div class="lr-strip"><div><p>${ui.esc(message)}</p>${ui.workspaceUrl?`<a class="btn small-btn" href="${ui.esc(ui.workspaceUrl+lrBase)}" target="_blank" rel="noopener">Open working app ↗</a>`:''}</div></div>`;
}
function lrSetupTabs(ui,part){return `<nav class="lr-look-tabs" aria-label="Your look">${[['hook','Hook'],['overlays','Overlays'],['cta','CTA']].map(([id,name])=>`<a href="${ui.esc(ui.href(lrBase+'/setup/'+id))}" data-route="${lrBase+'/setup/'+id}" ${part===id?'aria-current="page"':''}>${name}</a>`).join('')}</nav>`;}
function lrPreferencePrompt(f,d){
 const value=listLookAnswers(d.look,f.listReel?.fonts||[]),shot=f.listReel?.inputs?.selected;
 if(shot)value.shot=shot;
 return {value,text:'This is my preferred List Reel format. Save these reusable preferences, without creating a video. Choose the best hook and wording for each topic, audience and researched resource list. Do not ask me for a hook template or first line. Write fresh labels and CTA for each idea. Adapt the framing to the actual content when framing is adaptive, keeping it readable and leaving space for me.\n\n'+JSON.stringify(value,null,2)+'\n\nSave this JSON to workspace/library/scroll-reel-look.answers.json, then run node scripts/quick-cuts/scroll/save-look.mjs --answers workspace/library/scroll-reel-look.answers.json. Keep my other preference notes. Install any chosen custom fonts locally before a video uses them. Setup is done only when both preference files are saved.'};
}
function lrNewPrompt(f,d){
 const idea=lrList(f.listReel?.ideas?.items).find(i=>i.id===d.ideaId);
 const choice=d.choice==='own'?'My idea: '+d.topic.trim():d.choice==='saved'&&idea?'Use my saved idea '+idea.id+': '+idea.title+'.\n'+[idea.benefit,idea.why,idea.notes,...lrList(idea.links)].filter(Boolean).join('\n'):'Choose a useful idea from my unused saved ideas and shared audience context.';
 return '/quick-cuts scroll-reel\nMake '+d.count+' List Reel'+(d.count===1?'':'s')+'.\n'+choice+'\nKeep my saved visual identity and writing taste. Choose the best hook and wording for this subject and audience. Do not ask me to select or write a hook template. Write fresh labels and CTA for the researched resources. Fit the resource window to what needs showing, such as a paper, chart, website or video, while keeping the person and words clear. '+(f.listReel?.inputs?.selected?'Reuse this original take: '+f.listReel.inputs.selected+'. ':'')+'Research four complementary resources for each reel, verify their claims and choose the useful moments to show. Treat my idea choice as the direction; do not ask me to choose it again. Show the hook, all four resources and CTA for approval before captures. Do the preparation and checks, then show the reel and caption.';
}
function lrResearchPrompt(snapshot){const c=snapshot.account?.context||{};return '/quick-cuts scroll-reel\nResearch useful List Reel ideas from my saved audience, context and unused ideas. '+(c.audience?'Audience: '+c.audience+'. ':'')+(c.need?'They need: '+c.need+'. ':'')+'Save three concrete ideas in workspace/library/scroll-reel.ideas.json with a useful benefit, rationale and source provenance. Keep my unused ideas. Verify the actual sources before calling a list researched. Research only; do not capture or make a video yet.';}
function lrPreparePrompt(f){return 'Prepare my List Reel takes, a reusable collection of four or five variations with me visible, not random cutaways: '+lrList(f.listReel?.inputs?.clips).map(c=>c.path).join(', ')+'. Run intake and read-take on each original. Check that the resource window and words fit without hiding my face. Keep the take continuous and save the real readings. Do not render a reel yet.';}
function lrTasks(snapshot,project=null){const ids=new Set(lrList(snapshot.projects).filter(p=>p.format==='scroll-reel').map(p=>p.id));return lrList(snapshot.tasks).filter(t=>(project?t.project===project.id:t.format==='scroll-reel'||t.format==='research-reel'||ids.has(t.project)||/^(?:list-reel|scroll-reel)/.test(t.id||''))&&!['done','complete','completed'].includes(t.status));}
function lrTaskRows(snapshot,ui,project=null){return lrTasks(snapshot,project).map(t=>{
 const running=t.status==='running'&&!t.stale,status=t.stale||['paused','interrupted','stopped'].includes(t.status)?'Paused':['error','failed'].includes(t.status)?'Needs attention':running?'Agent working':t.status==='queued'?'Queued':'Waiting';
 const counts=Number.isFinite(t.completed)&&Number.isFinite(t.total)&&t.total>0?`<progress value="${Math.max(0,Math.min(t.total,t.completed))}" max="${t.total}" aria-label="${ui.esc(t.label||t.id)}"></progress><p class="small">${t.completed} of ${t.total}</p>`:'';
 return `<div class="lr-strip"><div><div class="lr-task-title">${running?'<i class="spin" aria-hidden="true"></i>':''}<strong>${ui.esc(t.label||t.title||'List Reel')}</strong><span class="lr-tag">${status}</span></div>${t.stage||t.message?`<p>${ui.esc(t.message||t.stage)}</p>`:''}${counts}</div></div>`;
 }).join('');}
function lrOverviewExample(f,ui){
 const example=f.listReel?.filming?.video||f.listReel?.preview?.background,poster=f.listReel?.filming?.poster||f.listReel?.preview?.poster,hasInputs=f.listReel?.inputs?.total,ready=listSetupDone(f);
 const action=!ready?['Choose your look','/setup','arrow']:!hasInputs?['Add your inputs','/inputs','upload']:['New List Reel','/new','plus'];
 return `<section class="lr-split lr-overview-example"><div class="lr-intro lr-overview-copy"><h1>Four useful things.<br>One reel.</h1><p>A real page, video or useful action. Over one original take of you.</p><div class="button-row lr-overview-cta">${ui.link(action[0],lrBase+action[1],'primary',action[2])}</div><div class="lr-timeline">${['Hook','1','2','3','4','CTA'].map(x=>`<div>${x}<small>One beat bar</small></div>`).join('')}</div></div><figure class="lr-example">${example?.url?`<video src="${ui.esc(example.url)}" ${poster?.url?`poster="${ui.esc(poster.url)}"`:''} controls playsinline preload="metadata" aria-label="Original footage from the reverse-engineering reel"></video>`:f.example?.url?`<img src="${ui.esc(f.example.url)}" alt="List Reel example">`:'<div class="lr-empty">The example is not installed yet.</div>'}<figcaption>Original footage. Your resources go on top.</figcaption></figure></section>`;
}

function lrOverview(f,snapshot,d,ui){
 const active=lrList(snapshot.projects).filter(p=>p.format===f.id&&!p.completed),outputs=lrList(snapshot.outputs).filter(o=>o.format===f.id).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));
 return `<section class="lr-section" data-list-output-section ${outputs.length?'':'hidden'}><h2>Your reels</h2><div data-list-live="outputs">${ui.outputCards(outputs)}</div></section><div data-list-live="tasks">${lrTaskRows(snapshot,ui)}</div><section class="lr-section" data-list-active-section ${active.length?'':'hidden'}><h2>In progress</h2><div data-list-live="projects">${ui.projectRows(active)}</div></section><div data-list-live="overview-example">${lrOverviewExample(f,ui)}</div>`;
}

function lrInputRows(f,d,ui){return lrList(f.listReel?.inputs?.clips).map(c=>`<label class="lr-input-row"><input type="radio" name="list-take" data-list-select="${ui.esc(c.path)}" ${f.listReel.inputs.selected===c.path?'checked':''} ${ui.preview?'disabled':''}>${c.thumbnail?.url?`<img src="${ui.esc(c.thumbnail.url)}" alt="" loading="lazy">`:''}<div><strong>${ui.esc(c.name)}</strong><small>${Number.isFinite(c.duration)?c.duration.toFixed(1)+'s · ':''}${ui.esc(c.reason||'Prepared original')}</small></div><span class="lr-tag ${c.prepared?'good':''}">${c.prepared?'Ready':'To prepare'}</span>${c.url?`<a href="${ui.esc(c.url)}" target="_blank" rel="noopener">View ↗</a>`:''}</label>`).join('')||'<div class="lr-empty"><p>Add one original take to reuse.</p></div>';}
function lrUploadRows(snapshot,ui){return [...lrJobs(snapshot).values()].filter(j=>j.status!=='done').map(j=>`<div class="lr-upload" data-list-upload-row="${j.id}"><div><span>${ui.esc(j.name)}</span><span data-list-upload-status>${ui.esc(j.error||j.status)}</span></div><progress value="${j.progress||0}" max="100" aria-label="Uploading ${ui.esc(j.name)}"></progress>${j.status==='error'?lrButton(ui,'Retry','retry-upload','small-btn',`data-id="${j.id}"`):''}</div>`).join('');}
function lrFilmingGuide(f,ui){
 const guide=f.listReel?.filming||{},video=guide.video,frames=lrList(guide.frames);
 return `<section class="lr-filming"><div class="lr-filming-example">${video?.url?`<video src="${ui.esc(video.url)}" ${guide.poster?.url?`poster="${ui.esc(guide.poster.url)}"`:''} controls playsinline preload="metadata" aria-label="Original footage from the reverse-engineering reel"></video>`:'<div class="lr-filming-sketch" aria-label="An upright phone filming a person at work">'+ui.icon('phone')+'<span>Phone down → You working</span></div>'}${guide.credit?`<p class="lr-filming-credit">${guide.link?lrSource(ui,guide.link,guide.credit):ui.esc(guide.credit)}</p>`:''}</div><div class="lr-filming-copy"><h2>You, doing something real.</h2><p>Set the phone down. Settle into the shot. Work, read, or carry on with your day.</p><div class="lr-filming-facts"><span>4 or 5 takes</span><span>About 15 seconds each</span><span>Vertical · unedited</span></div>${frames.length?`<div class="lr-filming-sequence">${frames.slice(0,3).map((frame,i)=>`<figure><img src="${ui.esc(frame.url)}" alt="${['Get ready in the shot','Settle into the shot','Keep doing your thing'][i]}"><figcaption><span>0${i+1}</span>${['Get ready','Settle in','Keep going'][i]}</figcaption></figure>`).join('')}</div>`:''}<p class="lr-hint">Keep yourself visible, with space above for the resources. No talking or captions.</p></div></section>${filmingGuide(ui,'scroll-reel')}`;
}
function lrInputs(f,snapshot,d,ui){
 const inputs=f.listReel?.inputs||{};
 return lrTitle(ui,'Film your List Reels.','A small collection of takes to use again.')+`${ui.preview?lrLiveLink(ui):`<div class="lr-drop" data-list-drop>${ui.icon('upload')}<strong>Add your original takes</strong><p class="small">You in the shot. One unbroken recording each.</p><label class="btn primary">Choose footage<input type="file" accept="video/*,.mov,.mkv" multiple data-list-upload aria-label="Choose original footage"></label></div>`}<div id="list-uploads" role="status">${lrUploadRows(snapshot,ui)}</div>`+lrFilmingGuide(f,ui)+`<section class="lr-input-shelf"><div class="lr-section-head"><h2>Your takes</h2><span class="small">${inputs.total||0} added · aim for 4 or 5</span></div><div data-list-live="inputs">${lrInputRows(f,d,ui)}</div>${lrList(inputs.available).length?`<details class="lr-details" data-list-detail="reuse"><summary>Reuse a suitable take from another format</summary><p class="lr-hint">Choose continuous footage with you visible and room for the resources.</p>${inputs.available.map(c=>`<label class="lr-input-row"><input type="checkbox" data-list-reuse="${ui.esc(c.path)}" ${d.reuse.includes(c.path)?'checked':''} ${ui.preview?'disabled':''}><div><strong>${ui.esc(c.name)}</strong></div>${c.url?`<a href="${ui.esc(c.url)}" target="_blank" rel="noopener">View ↗</a>`:''}</label>`).join('')}${lrButton(ui,'Add selected takes','reuse','small-btn',ui.preview?'disabled':'')}</details>`:''}${lrError()}<div class="lr-footer">${ui.link('Back',lrBase,'ghost')}${lrButton(ui,listSetupDone(f)?'Copy preparation prompt':'Choose your look',listSetupDone(f)?'prepare':'inputs-next','primary')}</div></section>`;
}
function lrIdeaRows(f,d,ui){const ideas=lrList(f.listReel?.ideas?.items).filter(i=>d.ideaFilter==='all'||d.ideaFilter==='suggested'?d.ideaFilter==='all'||['suggested','shortlisted'].includes(i.status):i.status===d.ideaFilter);return ideas.length?ideas.map((idea,i)=>`<article class="lr-idea"><span class="lr-idea-number">${String(i+1).padStart(2,'0')}</span><div><h3>${ui.esc(idea.title)}</h3>${idea.benefit?`<p>${ui.esc(idea.benefit)}</p>`:''}${idea.why?`<p class="small">${ui.esc(idea.why)}</p>`:''}<div class="lr-idea-meta"><span class="lr-tag">${ui.esc(idea.status)}</span><small>${idea.researchStatus==='ready'?'Research checked':idea.researchStatus==='needs-review'?'Research needs review':'To research'}</small></div><details class="lr-details" data-list-detail="idea-${ui.esc(idea.id)}"><summary>Notes and sources</summary>${idea.notes?`<p>${ui.esc(idea.notes)}</p>`:''}${lrList(idea.links).map(link=>`<p>${lrSource(ui,link,link)}</p>`).join('')}<div class="button-row">${ui.link('Edit',lrBase+'/ideas/new?edit='+encodeURIComponent(idea.id),'ghost small-btn')}${lrButton(ui,'Archive','idea-archive','ghost small-btn',`data-id="${ui.esc(idea.id)}" ${ui.preview?'disabled':''}`)}</div></details></div>${['suggested','shortlisted'].includes(idea.status)?lrButton(ui,'Save','idea-save','small-btn',`data-id="${ui.esc(idea.id)}" ${ui.preview?'disabled':''}`):''}${ui.link('Use idea',lrBase+'/new?idea='+encodeURIComponent(idea.id),'small-btn','arrow')}</article>`).join(''):'<div class="lr-empty"><p>No ideas here yet. Save a thought or ask for a few suggestions.</p></div>';}
function lrIdeas(f,d,ui){return lrTitle(ui,'Your idea bucket','Keep the useful ones.',ui.link('Add idea',lrBase+'/ideas/new','primary','plus'))+(ui.preview?lrLiveLink(ui):'')+`<div class="lr-idea-tools"><div class="lr-segments">${[['saved','Saved'],['suggested','Suggested'],['used','Used'],['all','All']].map(([id,name])=>lrButton(ui,name,'filter','',`data-value="${id}" aria-pressed="${d.ideaFilter===id}"`)).join('')}</div>${ui.link('Research ideas',lrBase+'/research','text-link')}</div>${f.listReel?.ideas?.error?`<p class="lr-error">${ui.esc(f.listReel.ideas.error)}</p>`:''}<div data-list-live="ideas">${lrIdeaRows(f,d,ui)}</div>${lrError()}`;}
function lrIdeaForm(f,d,ui){const id=lrParam(ui,'edit'),idea=lrList(f.listReel?.ideas?.items).find(i=>i.id===id);if(d.ideaEdit!==id||!d.ideaForm){d.ideaEdit=id;d.ideaForm={title:idea?.title||'',benefit:idea?.benefit||'',why:idea?.why||'',notes:idea?.notes||'',links:lrList(idea?.links).join('\n')};d.ideaRevision=f.listReel?.ideas?.revision??null;d.ideaConflict=null;}
 return `<div class="lr-narrow">${lrTitle(ui,id?'Edit idea':'Save an idea','A sentence, a source or a useful result.')}${ui.preview?lrLiveLink(ui):''}${lrField(ui,'Idea','idea.title',d.ideaForm.title,false,'maxlength="300"')}${lrField(ui,'What people get','idea.benefit',d.ideaForm.benefit,false,'maxlength="1000"')}<details class="lr-details" data-list-detail="idea-fields" ${id?'open':''}><summary>Links and notes</summary>${lrField(ui,'Why this is useful','idea.why',d.ideaForm.why,true,'maxlength="2000"')}${lrField(ui,'Source links, one per line','idea.links',d.ideaForm.links,true)}${lrField(ui,'Notes','idea.notes',d.ideaForm.notes,true,'maxlength="5000"')}</details><div id="list-idea-conflict"></div>${lrError()}<div class="lr-footer">${ui.link('Back to ideas',lrBase+'/ideas','ghost')}${lrButton(ui,'Save idea','idea-submit','primary',ui.preview?'disabled':'')}</div></div>`;}
function lrNew(f,d,ui){if(!listSetupDone(f))return `<div class="lr-narrow">${lrTitle(ui,'Choose your look once.','Every reel after this uses the saved format.')}${ui.link('Set up List Reel',lrBase+'/setup','primary')}</div>`;
 if(!f.listReel?.inputs?.selected)return `<div class="lr-narrow">${lrTitle(ui,'Add your original take.','Your look is saved. Add footage before making a reel.')}<div class="button-row">${ui.link('Add inputs',lrBase+'/inputs','primary','upload')}${ui.link('Explore ideas',lrBase+'/ideas','ghost')}</div></div>`;
 const id=lrParam(ui,'idea'),ideas=lrList(f.listReel?.ideas?.items);if(id&&d.routeIdea!==id){d.routeIdea=id;d.ideaId=id;d.choice='saved';}const selected=ideas.find(i=>i.id===d.ideaId);
 return `<div class="lr-narrow">${lrTitle(ui,'New List Reel','Your saved look stays in place.')}<label class="lr-radio"><input type="radio" name="list-idea" data-list-choice value="auto" ${d.choice==='auto'?'checked':''}><span>Choose for me<small>Use my audience and unused ideas.</small></span></label><label class="lr-radio"><input type="radio" name="list-idea" data-list-choice value="saved" ${d.choice==='saved'?'checked':''} ${!ideas.length?'disabled':''}><span>Use a saved idea<small>${ui.esc(selected?.title||'Pick from your bucket.')}</small></span></label><label class="field" data-list-own="saved" ${d.choice==='saved'?'':'hidden'}><span>Saved idea</span><select data-list-field="ideaId"><option value="">Choose an idea</option>${ideas.map(i=>`<option value="${ui.esc(i.id)}" ${i.id===d.ideaId?'selected':''}>${ui.esc(i.title)}</option>`).join('')}</select></label><label class="lr-radio"><input type="radio" name="list-idea" data-list-choice value="own" ${d.choice==='own'?'checked':''}><span>I have an idea<small>A topic, a useful result or a source.</small></span></label><div data-list-own="own" ${d.choice==='own'?'':'hidden'}>${lrField(ui,'Your idea','topic',d.topic||'',true,'maxlength="3000"')}</div><div class="lr-quantity">${lrButton(ui,'−','minus','ghost','aria-label="One fewer reel"')}<input type="number" data-list-field="count" min="1" max="10" value="${d.count}" aria-label="Number of reels">${lrButton(ui,'+','plus','ghost','aria-label="One more reel"')}<span>reel${d.count===1?'':'s'}</span></div>${lrError()}<div class="lr-footer">${ui.link('Back',lrBase,'ghost')}${lrButton(ui,'Get prompt','new-prompt','primary')}</div></div>`;}
function lrResearchProjects(snapshot,ui){const projects=lrList(snapshot.projects).filter(p=>p.format==='scroll-reel'&&!p.completed);return projects.length?lrSection('Your lists',projects.map(p=>`<a class="project-row" href="${ui.esc(ui.href(lrBase+'/research/'+encodeURIComponent(p.id)))}" data-route="${lrBase+'/research/'+encodeURIComponent(p.id)}"><div><h3>${ui.esc(p.name)}</h3><p class="small">${ui.esc(p.steps?.find(s=>s.id===p.progress?.current)?.label||'Research')}</p></div>${ui.icon('arrow')}</a>`).join('')):'<div class="lr-empty"><h2>No research running</h2><p>Ask for ideas, then come back while the agent works.</p></div>';}
function lrResearch(snapshot,ui){const context=snapshot.account?.context||{};return lrTitle(ui,'Research','Find four things worth showing.',ui.link('Add an idea',lrBase+'/ideas/new','small-btn','plus'))+`<div class="lr-research-layout"><div><div data-list-live="tasks">${lrTaskRows(snapshot,ui)}</div><div data-list-live="research-projects">${lrResearchProjects(snapshot,ui)}</div>${context.readyForIdeas?lrPrompt(ui,lrResearchPrompt(snapshot),'research-copy'):`<div class="lr-strip"><div><h3>A little direction first</h3><p>Use your saved context, or add the audience details that are missing.</p></div>${ui.link('Add direction',lrBase+'/research/context','small-btn')}</div>`}</div><aside class="lr-research-aside"><h3>Your audience</h3><p>${ui.esc(context.audience||(context.readyForIdeas?'Use the saved account context.':'Not saved yet.'))}</p>${context.need?`<h3>What they need</h3><p>${ui.esc(context.need)}</p>`:''}<h3>While this runs</h3><p>Save another idea or add a background take.</p><div class="button-row">${ui.link('Ideas',lrBase+'/ideas','small-btn')}${ui.link('Inputs',lrBase+'/inputs','small-btn')}</div></aside></div>${lrError()}`;}
function lrContext(snapshot,d,ui){const context=snapshot.account?.context||{};d.audience??=context.audience||'';d.need??=context.need||'';if(context.readyForIdeas)return `<div class="lr-narrow">${lrTitle(ui,'Your direction is saved.','Research can use your shared context.')}${ui.link('Back to research',lrBase+'/research','primary')}</div>`;return `<div class="lr-narrow">${lrTitle(ui,'Who should this help?','Only the direction missing from your saved context.')}${!context.audience?lrField(ui,'Your audience','audience',d.audience,false,'maxlength="1000"'):`<p>${ui.esc(context.audience)}</p>`}${!context.need?lrField(ui,'What they need help with','need',d.need,true,'maxlength="2000"'):`<p>${ui.esc(context.need)}</p>`}${lrError()}<div class="lr-footer">${ui.link('Back',lrBase+'/research','ghost')}${lrButton(ui,'Copy direction prompt','context-copy','primary')}</div></div>`;}
function lrReviewDraft(project,d){const research=project.listReel?.research;if(!research)return null;let value=d.reviews[project.id];if(!value||!value.dirty&&value.revision!==research.revision){value={revision:research.revision,hook:{l1:research.hook?.l1||'',l2:research.hook?.l2||''},cards:lrList(research.cards).map(c=>({sourceName:c.name,name:c.name||'',line:c.line||''})),cta:[research.cta?.pre||research.cta?.l1,research.cta?.keyword,research.cta?.tail||research.cta?.l2].filter(Boolean).join(' '),replacements:{},changes:'',dirty:false};d.reviews[project.id]=value;}return value;}
function lrProjectSteps(project,ui){return `<nav data-list-live="progress" class="lr-project-steps" aria-label="Reel progress">${lrList(project.steps).map(s=>{const path=['research','list'].includes(s.id)?lrBase+'/research/'+encodeURIComponent(project.id):'/projects/'+encodeURIComponent(project.id)+'?stage='+s.id;return `<a href="${ui.esc(ui.href(path))}" data-route="${path}" ${s.id===project.progress?.current?'aria-current="step"':''}>${s.status==='done'?'✓ ':''}${ui.esc(s.label)}</a>`;}).join('')}</nav>`;}
function lrResourceReview(project,d,ui,snapshot){const research=project.listReel?.research,r=lrReviewDraft(project,d);if(!research)return `<div class="lr-narrow">${lrTitle(ui,project.name,'The researched list will appear here.')}<div data-list-live="tasks">${lrTaskRows(snapshot,ui,project)}</div>${lrButton(ui,'Copy continue request','continue','primary')}${ui.link('Back',lrBase,'ghost')}${lrError()}</div>`;const ready=project.steps?.find(s=>s.id==='research')?.status==='done';return lrProjectSteps(project,ui)+`<div class="lr-edit"><div id="list-project-preview"></div><div>${lrTitle(ui,'Your list, before we build.','Check the promise and the four useful resources.')}<div class="lr-fields-pair">${lrField(ui,'First hook line','review.hook.l1',r.hook.l1)}${lrField(ui,'Second hook line','review.hook.l2',r.hook.l2)}</div>${research.cards.map((card,i)=>`<article class="lr-resource"><div class="lr-resource-head"><span>${i+1}</span><div><h3>${ui.esc(card.name)}</h3>${card.why?`<p>${ui.esc(card.why)}</p>`:''}</div><span class="lr-tag">${ui.esc(card.shape||'scroll')}</span></div>${lrField(ui,'Overlay name','review.card.'+i+'.name',r.cards[i]?.name)}${fExplanation(project)?lrField(ui,'One useful line','review.card.'+i+'.line',r.cards[i]?.line):''}<details data-list-detail="source-${i}"><summary>Source and useful moment</summary><p>${lrSource(ui,card.url,card.name)}</p>${card.moment?`<p>${ui.esc(typeof card.moment==='string'?card.moment:JSON.stringify(card.moment))}</p>`:''}${card.proof?`<p>${ui.esc(card.proof.label||'Evidence')}: ${ui.esc(card.proof.value??'')}</p>`:''}${lrList(card.sources).map(source=>`<p>${lrSource(ui,typeof source==='string'?source:source?.url,typeof source==='string'?source:source?.title||source?.url)}</p>`).join('')}</details><details data-list-detail="replace-${i}"><summary>Replace this resource</summary>${lrField(ui,'What should we use instead?','review.replace.'+i,r.replacements[i]||'',true)}${lrButton(ui,'Copy replacement request','replace','small-btn',`data-index="${i}"`)}</details></article>`).join('')}${lrField(ui,'CTA','review.cta',r.cta,true)}<div data-list-live="research-notice">${lrResearchNotice(project,d,ui)}</div>${lrError()}<div class="lr-footer">${ui.link('Back',lrBase+'/research','ghost')}<div data-list-live="research-actions">${ready?lrButton(ui,'Copy approval prompt','approve-list','primary'):lrButton(ui,'Copy continue request','continue','primary')}</div></div></div></div>`;}
function lrResearchNotice(project,d,ui){const research=project.listReel?.research,r=d.reviews[project.id];if(r&&r.revision!==research?.revision)return '<p class="lr-message">The sources changed. Your draft is kept, but needs a fresh review.</p>'+lrButton(ui,'Replace draft with latest list','review-latest','small-btn');return project.steps?.find(step=>step.id==='research')?.status==='done'?'':'<p class="lr-message">The sources still need verification before approval.</p>';}
function fExplanation(project){return (project.listReel?.look?.label??project.listLookLabel)==='explanation';}
function lrVideo(project){return project.listReel?.checked?project.listReel?.preview?.video:null;}
function lrMedia(project,ui){const video=lrVideo(project),history=lrList(project.listReel?.preview?.previousRenders);return (video?`<figure class="lr-example"><video src="${ui.esc(video.url)}" ${project.completed&&project.listReel?.outputs?.cover?.url?`poster="${ui.esc(project.listReel.outputs.cover.url)}"`:''} controls playsinline preload="metadata" aria-label="${ui.esc(project.name)}"></video><figcaption>${project.completed?'Finished reel':'Checked preview'}</figcaption></figure>`:`<div class="lr-empty"><h2>${history.length?'Your preview needs an update':'The preview appears here'}</h2><p>It appears after the current version passes its checks.</p></div>`)+(history.length?`<details class="lr-details" data-list-detail="previous-renders"><summary>Previous renders</summary>${history.map(file=>`<p><a href="${ui.esc(file.url)}" target="_blank" rel="noopener">${ui.esc(file.name||file.path.split('/').at(-1))} ↗</a></p>`).join('')}</details>`:'');}
function lrOutputFiles(project,ui){const output=project.listReel?.outputs||{};return [['video','Download reel'],['links','Resource links'],['sound','Sound instructions'],['cover','Cover']].map(([key,name])=>output[key]?.url&&(key!=='video'||project.completed)?`<a class="btn small-btn" href="${ui.esc(output[key].url)}" download>${name}</a>`:'').join('');}
function lrProjectActions(project,ui){const step=project.steps?.find(s=>s.id===project.progress?.current);return project.completed?ui.link('New List Reel',lrBase+'/new','primary','plus'):`<div class="button-row">${lrButton(ui,'Copy changes','changes','small-btn')}${project.progress?.current==='review'&&step?.owner==='you'?lrButton(ui,'Approve reel and caption','approve-reel','primary'):lrButton(ui,'Copy continue request','continue','primary')}</div>`;}
function lrProject(project,snapshot,d,ui){const r=lrReviewDraft(project,d)|| (d.reviews[project.id]??={changes:'',dirty:false}),step=project.steps?.find(s=>s.id===project.progress?.current);return `<div data-list-live="project-heading">${lrTitle(ui,project.completed?'Your reel is ready.':project.name,project.completed?'Your video, caption and posting files.':step?.reason||'Continue this reel in chat.')}${lrProjectSteps(project,ui)}</div><div data-list-live="tasks">${lrTaskRows(snapshot,ui,project)}</div><div class="lr-review"><div data-list-live="project-media">${lrMedia(project,ui)}</div><div><h2>Caption</h2><div class="lr-caption" data-list-live="caption">${ui.esc(project.listReel?.caption?.text||'The caption appears when it is written.')}</div><div data-list-live="caption-action">${project.listReel?.caption?.text?lrButton(ui,'Copy caption','copy-caption','small-btn'):''}</div><div class="lr-output-files" data-list-live="output-files">${lrOutputFiles(project,ui)}</div><div data-list-changes ${project.completed?'hidden':''}>${lrField(ui,'Changes for this reel','review.changes',r.changes||'',true)}</div><div data-list-live="project-actions">${lrProjectActions(project,ui)}</div>${lrError()}</div></div>`;}

export function listReelPage(f,snapshot,parent,sub='',ui,project=null){
 const d=listDraft(f,parent);let page=sub.replace(/^\/+|\/+$/g,''),html='';
 if(page==='setup')page='setup/hook';
 if(page==='new/prompt'&&(!listSetupDone(f)||!f.listReel?.inputs?.selected))page='new';
 if(page.startsWith('research/')&&page!=='research/context'){project??=lrList(snapshot.projects).find(p=>p.id===decodeURIComponent(page.slice(9))&&p.format===f.id);page='research/project';}
 if(project&&page!=='research/project')page='project';
 if(project)project={...project,listLookLabel:project.listReel?.look?.label??f.answers?.label};
 if(page==='')html=lrOverview(f,snapshot,d,ui);
 else if(page==='inputs')html=lrInputs(f,snapshot,d,ui);
 else if(['setup/hook','setup/overlays','setup/cta'].includes(page))html='<div id="list-look"></div>'+lrError();
 else if(page==='setup/prompt'||page==='setup/waiting'){{const prompt=lrPreferencePrompt(f,d);d.preferencePrompt=prompt.text;d.pendingLook=prompt.value;}html=`<div class="lr-narrow">${lrTitle(ui,'Your preferred format.','Save this once in chat.')}<div id="list-save-state" class="lr-strip"><p>${d.saveConfirmed?'Your preferences are saved.':d.awaitingSave?'Waiting for the agent to save both preference files.':'Copying the prompt keeps your choices here; the agent saves them.'}</p></div>${lrPrompt(ui,d.preferencePrompt,'copy-preferences')}<div class="lr-footer">${ui.link('Edit look',lrBase+'/setup/hook','ghost')}${ui.link(d.saveConfirmed?'Return to List Reel':'Back to overview',lrBase,'small-btn')}</div></div>`;}
 else if(page==='ideas')html=lrIdeas(f,d,ui);
 else if(page==='ideas/new')html=lrIdeaForm(f,d,ui);
 else if(page==='new')html=lrNew(f,d,ui);
 else if(page==='new/prompt')html=`<div class="lr-narrow">${lrTitle(ui,'Your next List Reel.','The agent takes it from here.')}${lrPrompt(ui,d.newPrompt||lrNewPrompt(f,d))}<div class="lr-footer">${ui.link('Back',lrBase+'/new','ghost')}${ui.link('Watch progress',lrBase,'small-btn')}</div></div>`;
 else if(page==='research')html=lrResearch(snapshot,ui);
 else if(page==='research/context')html=lrContext(snapshot,d,ui);
  else if(page==='research/project'&&project)html=lrResourceReview(project,d,ui,snapshot);
 else if(page==='project'&&project)html=lrProject(project,snapshot,d,ui);
 else html=`<div class="lr-empty"><h1>This reel is no longer here.</h1>${ui.link('Back to List Reel',lrBase,'primary')}</div>`;
 return {page,project,html:`<div class="lr" data-list-page="${page}">${html}</div>`};
}

export function mountListReel(element,options){
 let {f,snapshot,d,page,project,ui}=options,disposed=false,look=null;
 const liveHTML=new Map(),workspaceKey=snapshot.workspaceId||'preview';
 const initialSetup=listSetupDone(f),initialResearch=project?.listReel?.research?.revision||null;
 const initialContext=JSON.stringify(snapshot.account?.context||{});
 const find=s=>element.querySelector(s),all=s=>[...element.querySelectorAll(s)];
 const persist=()=>ui.persist?.();
 const error=message=>{const node=find('#list-error');if(node){node.textContent=message;node.scrollIntoView?.({block:'nearest'});}else ui.toast?.(message);};
 const copy=(text,message,options)=>ui.copy(text,message,options);
 const navigate=path=>{if(disposed)return;persist();ui.navigate(path);};
 const refresh=async()=>{await ui.refresh?.();};
 const mutation=async(path,body)=>{if(ui.preview)throw Error('Open the working app to save this.');const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Keyframes-Write':'inputs'},body:JSON.stringify(body),cache:'no-store'});let result;try{result=await response.json();}catch{throw Error('Your folder could not be reached. Try again.');}if(!response.ok){const failure=Error(result.error||'This could not be saved.');failure.status=response.status;throw failure;}return result;};
 const actualFile=path=>lrList(snapshot.files).find(file=>file.path===path||file.url===path);
 function previewOptions(){
  const setup=f.listReel?.preview||{},fonts=f.listReel?.fonts||[];
  if(!project)return {fonts,value:d.look,background:setup.background,poster:setup.poster,resources:setup.resources,sample:!lrList(f.listReel?.inputs?.clips).some(c=>c.path===setup.background?.path)};
  const research=project.listReel?.research,source=project.listReel?.background||actualFile(project.sourcePath||project.data?.source)||actualFile(project.mezzaninePath||project.data?.mezzanine);
  const draft=d.reviews[project.id],editing=page==='research/project'&&draft?.revision===research?.revision;
  const content=research?{...research,hook:editing?draft.hook:research.hook,cta:editing&&draft.ctaDirty?{pre:draft.cta}:research.cta,cards:lrList(research.cards).map((card,index)=>{const path=project.data?.captures?.[card.name];const recording=card.recording||actualFile(path)||actualFile(project.path+'/'+path);return {...card,...(editing?{name:draft.cards[index]?.name??card.name,line:draft.cards[index]?.line??card.line}:{}),recording:recording||null,capture:null,media:null};})}:{hook:{l1:'',l2:''},cta:{},cards:[]};
  return {fonts,value:listLookAnswers(project.listReel?.look??{},fonts),layout:project.listReel?.layout,background:source||null,poster:null,resources:[],sample:false,content};
 }
 if(find('#list-look')){
  const part=page.split('/')[1],next=part==='hook'?'overlays':part==='overlays'?'cta':'prompt';
  look=mountListLook(find('#list-look'),{...previewOptions(),part,googleDraft:d.googleDraft||'',tabs:lrSetupTabs(ui,part),footer:`<div class="lr-footer">${ui.link('Back',part==='hook'?lrBase+'/inputs':lrBase+'/setup/'+(part==='overlays'?'hook':'overlays'),'ghost')}${lrButton(ui,next==='prompt'?'Get preference prompt':'Next: '+next,'look-next','primary',`data-next="${next}"`)}</div>`,onChange:value=>{d.look=value;d.lookDirty=true;d.saveConfirmed=false;persist();},onGoogleDraft:value=>{d.googleDraft=value;persist();}});
 }else if(find('#list-project-preview'))look=mountListLook(find('#list-project-preview'),{...previewOptions(),previewOnly:true});
 function live(name,html){const node=find(`[data-list-live="${name}"]`);if(!node||liveHTML.get(name)===html||node.contains(document.activeElement))return;const opened=[...node.querySelectorAll('details[open][data-list-detail]')].map(n=>n.dataset.listDetail),videos=new Map([...node.querySelectorAll('video')].map(video=>[video.getAttribute('src'),video]));node.innerHTML=html;for(const video of node.querySelectorAll('video')){const previous=videos.get(video.getAttribute('src'));if(previous)video.replaceWith(previous);}for(const key of opened)node.querySelector(`[data-list-detail="${CSS.escape(key)}"]`)?.setAttribute('open','');liveHTML.set(name,html);}
 function update(next={}){
  if(disposed)return;
  const incoming=next.snapshot||(next.formats?next:null);if(incoming)snapshot=incoming;f=next.f||snapshot.formats?.find(format=>format.id===f.id)||f;
  if(project)project=next.project||snapshot.projects?.find(p=>p.id===project.id)||project;
  if(page==='research/project'&&project&&(project.listReel?.research?.revision||null)!==initialResearch&&!d.reviews[project.id]?.dirty){ui.render?.();return;}
  if(page==='research'&&JSON.stringify(snapshot.account?.context||{})!==initialContext){ui.render?.();return;}
  if(page===''&&(listSetupDone(f)!==initialSetup||!find('[data-list-live="projects"]')&&(lrList(snapshot.projects).some(p=>p.format===f.id)||lrList(snapshot.outputs).some(o=>o.format===f.id)))){ui.render?.();return;}
  const saved=listLookAnswers(f.answers,f.listReel?.fonts||[]);if(d.pendingLook&&listSetupDone(f)&&lrEqual(saved,d.pendingLook)){d.awaitingSave=false;d.lookDirty=false;d.saveConfirmed=true;d.look=saved;persist();}
  if(look)look.update(previewOptions());
  live('tasks',lrTaskRows(snapshot,ui,project));
  if(page==='inputs'){live('inputs',lrInputRows(f,d,ui));uploads();}
  if(page==='ideas')live('ideas',lrIdeaRows(f,d,ui));
  if(page==='research')live('research-projects',lrResearchProjects(snapshot,ui));
  if(page==='research/project'&&project){const progress=find('[data-list-live="progress"]');if(progress)progress.outerHTML=lrProjectSteps(project,ui);live('research-notice',lrResearchNotice(project,d,ui));live('research-actions',project.steps?.find(step=>step.id==='research')?.status==='done'?lrButton(ui,'Copy approval prompt','approve-list','primary'):lrButton(ui,'Copy continue request','continue','primary'));}
  if(page===''){const active=lrList(snapshot.projects).filter(p=>p.format===f.id&&!p.completed),outputs=lrList(snapshot.outputs).filter(o=>o.format===f.id).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));live('projects',ui.projectRows(active));live('outputs',ui.outputCards(outputs));const outputSection=find('[data-list-output-section]'),activeSection=find('[data-list-active-section]');if(outputSection)outputSection.hidden=!outputs.length;if(activeSection)activeSection.hidden=!active.length;live('overview-example',lrOverviewExample(f,ui));}
  if(page==='project'&&project){const step=project.steps?.find(s=>s.id===project.progress?.current);live('project-heading',lrTitle(ui,project.completed?'Your reel is ready.':project.name,project.completed?'Your video, caption and posting files.':step?.reason||'Continue this reel in chat.')+lrProjectSteps(project,ui));live('project-media',lrMedia(project,ui));live('caption',ui.esc(project.listReel?.caption?.text||'The caption appears when it is written.'));live('caption-action',project.listReel?.caption?.text?lrButton(ui,'Copy caption','copy-caption','small-btn'):'');live('output-files',lrOutputFiles(project,ui));live('project-actions',lrProjectActions(project,ui));const changes=find('[data-list-changes]');if(changes)changes.hidden=Boolean(project.completed);}
  const state=find('#list-save-state p');if(state)state.textContent=d.saveConfirmed?'Your preferences are saved.':d.awaitingSave?'Waiting for the agent to save both preference files.':'Copying the prompt keeps your choices here; the agent saves them.';
 }
 function uploads(){if(!disposed&&find('#list-uploads'))find('#list-uploads').innerHTML=lrUploadRows(snapshot,ui);}
 async function runUpload(job){job.status='uploading';job.error='';lrUploadNotify(snapshot);try{await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();job.xhr=xhr;xhr.open('PUT','/api/list-inputs?name='+encodeURIComponent(job.file.webkitRelativePath||job.name));xhr.setRequestHeader('X-Keyframes-Write','inputs');xhr.upload.onprogress=e=>{if(e.lengthComputable)job.progress=Math.round(e.loaded/e.total*100);lrUploadNotify(snapshot);};xhr.onload=()=>{let value;try{value=JSON.parse(xhr.responseText);}catch{}if(xhr.status>=200&&xhr.status<300)resolve(value);else reject(Error(value?.error||'The upload failed. Try again.'));};xhr.onerror=()=>reject(Error('The connection stopped. Retry this upload.'));xhr.onabort=()=>reject(Error('Upload stopped.'));xhr.send(job.file);});job.status='done';job.progress=100;job.file=null;await refresh();}catch(e){job.status='error';job.error=e.message;}finally{delete job.xhr;lrUploadNotify(snapshot);}}
 async function addFiles(files){if(ui.preview){error('Open the working app to add originals.');return;}const accepted=[...files].filter(file=>/\.(mp4|mov|m4v|mkv|webm|avi)$/i.test(file.name));if(!accepted.length){error('Choose an original video clip.');return;}const jobs=accepted.map(file=>({id:crypto.randomUUID(),name:file.name,file,status:'queued',progress:0}));for(const job of jobs)lrJobs(snapshot).set(job.id,job);uploads();for(const job of jobs)await runUpload(job);}
 const input=e=>{const target=e.target,key=target.dataset.listField;if(!key)return;if(key.startsWith('idea.'))d.ideaForm[key.slice(5)]=target.value;else if(key.startsWith('review.')){if(!project)return;const r=lrReviewDraft(project,d)||d.reviews[project.id],parts=key.split('.');r.dirty=true;if(parts[1]==='hook')r.hook[parts[2]]=target.value;else if(parts[1]==='card')r.cards[Number(parts[2])][parts[3]]=target.value;else if(parts[1]==='replace')r.replacements[parts[2]]=target.value;else{r[parts[1]]=target.value;if(parts[1]==='cta')r.ctaDirty=true;}if(look&&page==='research/project')look.update(previewOptions());}else d[key]=key==='count'?Math.min(10,Math.max(1,Number(target.value)||1)):target.value;persist();};
 const change=async e=>{const target=e.target;try{if(target.hasAttribute('data-list-upload')){await addFiles(target.files);target.value='';}else if(target.dataset.listSelect){await mutation('/api/list-inputs',{action:'select',path:target.dataset.listSelect});await refresh();}else if(target.dataset.listReuse){d.reuse=target.checked?[...new Set([...d.reuse,target.dataset.listReuse])]:d.reuse.filter(path=>path!==target.dataset.listReuse);persist();}else if(target.hasAttribute('data-list-choice')){d.choice=target.value;all('[data-list-own]').forEach(node=>node.hidden=node.dataset.listOwn!==d.choice);persist();}}catch(e){error(e.message);}};
 const click=async e=>{const button=e.target.closest('[data-list-action]');if(!button||!element.contains(button)||button.disabled)return;const action=button.dataset.listAction;try{
  if(action==='look-next'){const problem=look?.validate();if(problem)throw Error(problem);d.look=look.value;if(button.dataset.next==='prompt'){const generated=lrPreferencePrompt(f,d);d.preferencePrompt=generated.text;d.pendingLook=generated.value;d.saveConfirmed=false;d.awaitingSave=false;}navigate(lrBase+'/setup/'+button.dataset.next);}
  else if(action==='inputs-next')navigate(lrBase+'/setup/hook');
  else if(action==='copy-preferences'){await copy(d.preferencePrompt);d.awaitingSave=!d.saveConfirmed;persist();update();}
  else if(action==='copy-prompt')await copy(find('#list-prompt')?.textContent||'');
  else if(action==='prepare'){if(!f.listReel?.inputs?.clips?.length)throw Error('Add an original take first.');await copy(lrPreparePrompt(f));}
  else if(action==='reuse'){if(!d.reuse.length)throw Error('Choose the takes to reuse.');button.disabled=true;await mutation('/api/list-inputs',{action:'reuse',paths:d.reuse});d.reuse=[];persist();await refresh();ui.toast?.('Originals added.');}
  else if(action==='retry-upload'){const job=lrJobs(snapshot).get(button.dataset.id);if(!job?.file)throw Error('Choose this file again.');await runUpload(job);}
  else if(action==='filter'){d.ideaFilter=button.dataset.value;persist();all('[data-list-action="filter"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.value===d.ideaFilter));live('ideas',lrIdeaRows(f,d,ui));}
  else if(action==='idea-submit'){if(!d.ideaForm.title.trim())throw Error('Give this idea a title.');button.disabled=true;const idea={...d.ideaForm,links:d.ideaForm.links.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)};await mutation('/api/list-reel',{action:d.ideaEdit?'update':'add',id:d.ideaEdit||undefined,revision:d.ideaRevision,idea});d.ideaForm=null;d.ideaEdit=null;navigate(lrBase+'/ideas');await refresh();ui.toast?.('Idea saved.');}
  else if(action==='idea-save'||action==='idea-archive'){button.disabled=true;await mutation('/api/list-reel',{action:action==='idea-save'?'save':'archive',id:button.dataset.id,revision:f.listReel?.ideas?.revision??null});await refresh();}
  else if(action==='idea-latest'){button.disabled=true;const response=await fetch('/api/workspace',{cache:'no-store'});if(!response.ok)throw Error('The latest ideas could not be read.');const fresh=await response.json();update(fresh);d.ideaRevision=f.listReel?.ideas?.revision??null;d.ideaConflict=lrList(f.listReel?.ideas?.items).find(i=>i.id===d.ideaEdit)||null;find('#list-idea-conflict').innerHTML=d.ideaConflict?`<details class="lr-details" open><summary>Latest saved version</summary><p>${ui.esc(d.ideaConflict.title)}</p><p>${ui.esc(d.ideaConflict.benefit||d.ideaConflict.notes||'')}</p><p class="small">Your draft is kept above. Review it before saving again.</p></details>`:'';persist();error('Latest ideas loaded. Your draft is kept.');}
  else if(action==='plus'||action==='minus'){d.count=Math.min(10,Math.max(1,d.count+(action==='plus'?1:-1)));find('[data-list-field="count"]').value=d.count;persist();}
  else if(action==='new-prompt'){if(!listSetupDone(f))throw Error('Save your look once before making a reel.');if(!f.listReel?.inputs?.selected){navigate(lrBase+'/inputs');return;}if(d.choice==='own'&&!d.topic?.trim())throw Error('Write the idea you want to use.');if(d.choice==='saved'&&!lrList(f.listReel?.ideas?.items).some(i=>i.id===d.ideaId))throw Error('Choose an idea from your bucket.');d.newPrompt=lrNewPrompt(f,d);navigate(lrBase+'/new/prompt');}
  else if(action==='research-copy')await copy(lrResearchPrompt(snapshot));
  else if(action==='context-copy'){if(!d.audience.trim()||!d.need.trim())throw Error('Add the audience and what they need.');await copy('Use this shared audience direction.\nAudience: '+d.audience.trim()+'\nNeed: '+d.need.trim()+'\nSave this in my shared context with buyer provenance, then suggest three relevant List Reel ideas. Keep any context already known. Research only; no capture or rendering.');}
  else if(action==='continue')await copy('/quick-cuts scroll-reel\nContinue '+project.path+'. Read its actual steps and preserve approved work. Resolve the current missing checks, then show the next result for review. Do the preparation and production work yourself; ask me only for a missing personal answer or a required sign-in.');
  else if(action==='replace'){const r=d.reviews[project.id],index=Number(button.dataset.index),note=r.replacements[index]?.trim();if(!note)throw Error('Describe the replacement or paste its source.');await copy('/quick-cuts scroll-reel\nIn '+project.path+', replace only '+project.listReel.research.cards[index].name+': '+note+'\nKeep the other resources and saved look. Verify the replacement, update only dependent work and show the revised list before capture. Current list revision: '+r.revision);}
  else if(action==='review-latest'){delete d.reviews[project.id];persist();if(!disposed)ui.render?.();}
  else if(action==='approve-list'){const r=d.reviews[project.id];if(project.steps?.find(step=>step.id==='research')?.status!=='done')throw Error('The sources need verification before approval.');if(project.listReel?.research?.revision!==r.revision)throw Error('The list changed. Use Replace draft with latest list and review the sources before approving.');if(!r.hook.l1.trim()||!r.hook.l2.trim()||!r.cta.trim()||r.cards.length!==4||r.cards.some(c=>!c.name.trim()))throw Error('Keep both hook lines, all four resource names and the CTA.');await copy('/quick-cuts scroll-reel\nI approve this list and its words for '+project.path+'.\nSource revision: '+r.revision+'\n'+JSON.stringify({hook:r.hook,cards:r.cards,cta:r.cta},null,2)+'\nKeep the verified resource identities and my saved look. Apply these words, check the list and record approval tied to its current revision with scripts/quick-cuts/scroll/steps.mjs. Capture each useful moment, check every recording, then show the reel and caption.');}
  else if(action==='copy-caption')await copy(project.listReel?.caption?.text||'','Caption copied.',{literal:true});
  else if(action==='changes'){const note=d.reviews[project.id]?.changes?.trim();if(!note)throw Error('Write the changes you want first.');await copy('/quick-cuts scroll-reel\nChange '+project.path+': '+note+'\nKeep the saved look and other approved work. Reopen only the affected checks and show the updated reel and caption.');}
  else if(action==='approve-reel')await copy('/quick-cuts scroll-reel\nI approve this reel and caption: '+project.path+'.\nReview revision: '+(project.listReel?.reviewRevision||project.progress?.reviewRevision||'read the current revision')+'\nRecord approval for this exact revision, run the final checks and export the video, caption, links, cover and sound instructions.');
 }catch(failure){error(failure.message);if(failure.status===409&&action==='idea-submit'){const host=find('#list-idea-conflict');if(host)host.innerHTML=lrButton(ui,'Review latest ideas','idea-latest','small-btn');}}finally{if(!disposed&&button.isConnected)button.disabled=false;}};
 const drag=e=>{const drop=e.target.closest('[data-list-drop]');if(!drop)return;e.preventDefault();drop.classList.toggle('dragging',e.type!=='dragleave'&&e.type!=='drop');if(e.type==='drop')addFiles(e.dataTransfer.files);};
 if(!lrUploadListeners.has(workspaceKey))lrUploadListeners.set(workspaceKey,new Set());lrUploadListeners.get(workspaceKey).add(uploads);
 element.addEventListener('click',click);element.addEventListener('input',input);element.addEventListener('change',change);for(const event of ['dragover','dragenter','dragleave','drop'])element.addEventListener(event,drag);
 return {update,destroy(){disposed=true;look?.destroy();lrUploadListeners.get(workspaceKey)?.delete(uploads);element.removeEventListener('click',click);element.removeEventListener('input',input);element.removeEventListener('change',change);for(const event of ['dragover','dragenter','dragleave','drop'])element.removeEventListener(event,drag);}};
}
